mapper.select:
select ,m.phone member_phone, case when r.anonymous='1' then '匿名用户' else coalesce(nullif(m.nickname,''), concat(left(m.phone,3),'****',right(m.phone,4))) end reviewer_name from mall_product_review r join mall_member m on m.member_id=r.member_id where 1=1 and r.status=#{status} and r.spu_id=#{spuId}
and (r.product_name like concat('%',#{keyword},'%') or r.content like concat('%',#{keyword},'%') or r.order_no like concat('%',#{keyword},'%'))
order by case when r.status='PENDING' then 0 else 1 end,r.create_time desc,r.review_id desc
